class Zipper:
    """An immutable focus into a tree of value/left/right dictionaries.

    Missing children are represented by None. Each breadcrumb records the
    parent and the branch taken, so edits can be rebuilt on the way up.
    """

    def __init__(self, tree, breadcrumbs=()):
        self._tree = tree
        self._breadcrumbs = breadcrumbs

    @staticmethod
    def from_tree(tree):
        return Zipper(deepcopy(tree))

    def value(self):
        return deepcopy(self._tree["value"])

    def set_value(self, value):
        return Zipper(
            {**self._tree, "value": deepcopy(value)}, self._breadcrumbs
        )

    def left(self):
        return self._down("left")

    def set_left(self, tree):
        return Zipper(
            {**self._tree, "left": deepcopy(tree)}, self._breadcrumbs
        )

    def right(self):
        return self._down("right")

    def set_right(self, tree):
        return Zipper(
            {**self._tree, "right": deepcopy(tree)}, self._breadcrumbs
        )

    def _down(self, branch):
        child = self._tree[branch]
        if child is None:
            return None
        return Zipper(child, self._breadcrumbs + ((self._tree, branch),))

    def up(self):
        if not self._breadcrumbs:
            return None
        parent, branch = self._breadcrumbs[-1]
        return Zipper(
            {**parent, branch: self._tree}, self._breadcrumbs[:-1]
        )

    def to_tree(self):
        zipper = self
        while zipper._breadcrumbs:
            zipper = zipper.up()
        return deepcopy(zipper._tree)
